    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
# Gather paint features across all 5 demos: for each painted row, record comp bbox, row fg-run end, tail len, whether row's fg pattern is periodic (find smallest p>=2 with consistent repetition after some point).
for n in ['1','2','3','4','5']:
    gi=np.array(G[f'Demo pair {n} input']); go=np.array(G[f'Demo pair {n} output'])
    vals=collections.Counter(gi.ravel()); bg=vals.most_common(1)[0][0]
    # components
    seen=[[False]*gi.shape[1] for _ in range(gi.shape[0])]
    comps=[]
    for i in range(gi.shape[0]):
        for j in range(gi.shape[1]):
            if gi[i,j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<gi.shape[0] and 0<=y<gi.shape[1] and not seen[x][y] and gi[x,y]!=bg:
                            seen[x,y]=True; st.append((x,y))
                comps.append(comp)
    print('=== demo',n,'comp info:')
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        rr0,rr1=min(rs),max(rs); cc0,cc1=min(cs),max(cs)
        paints=[]
        for i in range(rr0,rr1+1):
            nz=[j for j,x in enumerate(gi[i]) if x!=bg and cc0<=j<=cc1]
            if any(go[i,j]!=gi[i,j] for j in nz):
                passes=[j for j in range(nz[-1]+1,gi.shape[1]) if go[i,j]==1]
                paints.append((i,max(nz),len(range(max(nz)+1,gi.shape[1])),passes))
        for p in paints: print('   ',p)

