def comps_of(inp):
    # connected non-bg components with their cells
    H,W=inp.shape; bg=collections.Counter(inp.ravel()).most_common(1)[0][0]
    seen=np.zeros_like(inp,bool); out=[]
    for i in range(H):
        for j in range(W):
            if inp[i,j]!=bg and not seen[i,j]:
                st=[(i,j)]; seen[i,j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and not seen[x,y] and inp[x,y]!=bg:
                            seen[x,y]=True; st.append((x,y))
                out.append(cells)
    return inp,bg,out

