def solve(gi):
    H,W=gi.shape
    bg=collections.Counter(gi.ravel()).most_common(1)[0][0]
    best=None
    # try vertical split: divide into two overlapping regions; find dy,dx such that region A shifted equals region B as much as possible
    res=[]
    for dy in range(1,H//2+2):
        for dx in range(-W,W+1):
            nconf=0; ntotal=0
            for r in range(H-dy):
                for c in range(W-abs(dx)):
                    v1=(gi[r,c]!=bg); v2=(gi[r+dy,c-dx]!=bg)
                    ntotal+=1
                    if v1!=v2: nconf+=1
            res.append((-nconf/ntotal,dy,dx))
    res.sort(reverse=True)
    score,dy,dx=res[0]; print('demo ok:',score,dy,dx,'conflicts',round(-ntotal*score,2))
    return score,dy,dx

